// Des: Tests for ob-aler-send: both channels, one down, none configured
// Flo: fake transport records calls > send alerts > assert shapes and counts
// I/O: fake HTTP > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const aler = @import("ob-aler-send.zig"); const base = @import("nt-vend-base.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Fake = struct { cod2: [2]u16 = .{ 200, 200 }, seen: [2]?base.Http = .{ null, null }, bodi: [2][512]u8 = undefined, lens: [2]usize = .{ 0, 0 }, numb: usize = 0, pub fn send(self: *Fake) base.Send { return .{ .ctx2 = self, .call = cal2 }; } fn cal2(ctx2: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, http: base.Http) anyerror!base.Back { const self: *Fake = @ptrCast(@alignCast(ctx2)); const ind3 = @min(self.numb, 1); self.numb += 1; const room = @min(http.body.len, 512); @memcpy(self.bodi[ind3][0..room], http.body[0..room]); self.lens[ind3] = room; self.seen[ind3] = http; return .{ .code = self.cod2[ind3], .body = try gpaz.dupe(u8, "") }; } };
test "both channels are used: ping to /fail, email via Resend with Bearer" { var fakz: Fake = .{}; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const alzz: aler.Aler = .{ .send = fakz.send(), .gpaz = allo, .hcur = "https://hc-ping.com/abc-123/", .rkey = "re_KEY", .from = "scra@x.dev", .toxx = "me@x.dev" }; try std.testing.expectEqual(@as(u8, 2), try aler.alerSend(&alzz, aren.allocator(), std.testing.io, "scra halted", "breaker tripped")); try std.testing.expectEqualStrings("https://hc-ping.com/abc-123/fail", fakz.seen[0].?.urlz); try std.testing.expectEqualStrings("https://api.resend.com/emails", fakz.seen[1].?.urlz); try std.testing.expectEqualStrings("Bearer re_KEY", fakz.seen[1].?.auth); try std.testing.expectEqualStrings("{\"from\":\"scra@x.dev\",\"to\":[\"me@x.dev\"],\"subject\":\"scra halted\",\"text\":\"breaker tripped\"}", fakz.bodi[1][0..fakz.lens[1]]); }
test "one channel down still counts as delivered; all down is an error" { var fakz: Fake = .{ .cod2 = .{ 500, 200 } }; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const alzz: aler.Aler = .{ .send = fakz.send(), .gpaz = allo, .hcur = "https://hc-ping.com/x", .rkey = "k", .from = "a@b.c", .toxx = "d@e.f" }; try std.testing.expectEqual(@as(u8, 1), try aler.alerSend(&alzz, aren.allocator(), std.testing.io, "s", "t")); var dead: Fake = .{ .cod2 = .{ 500, 500 } }; const al2z: aler.Aler = .{ .send = dead.send(), .gpaz = allo, .hcur = "https://hc-ping.com/x", .rkey = "k", .from = "a@b.c", .toxx = "d@e.f" }; try std.testing.expectError(error.AlertFail, aler.alerSend(&al2z, aren.allocator(), std.testing.io, "s", "t")); }
test "nothing configured, or email half-configured, sends nothing" { var fakz: Fake = .{}; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const none: aler.Aler = .{ .send = fakz.send(), .gpaz = allo }; try std.testing.expectError(error.AlertFail, aler.alerSend(&none, aren.allocator(), std.testing.io, "s", "t")); const half: aler.Aler = .{ .send = fakz.send(), .gpaz = allo, .rkey = "k" }; try std.testing.expectError(error.AlertFail, aler.alerSend(&half, aren.allocator(), std.testing.io, "s", "t")); try std.testing.expectEqual(@as(usize, 0), fakz.numb); }
test "key files load, missing ones are empty (channel skipped)" { var fakz: Fake = .{}; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const dirz = try std.fmt.allocPrint(aren.allocator(), ".zig-cache/tmp/{s}", .{tmpz.sub_path}); try tmpz.dir.writeFile(std.testing.io, .{ .sub_path = "resend.key", .data = " re_ABC \r\nignored\n" }); var conf: cfgz.Conf = .{}; conf.aler_mail_from = "f@x.y"; conf.aler_mail_toxx = "t@x.y"; const alzz = aler.alerLoad(aren.allocator(), std.testing.io, dirz, conf, fakz.send(), allo); try std.testing.expectEqualStrings("re_ABC", alzz.rkey); try std.testing.expectEqualStrings("", alzz.hcur); }
